import{_ as u,a0 as s,w as o,s as p,ao as g,I as l,x as i,a1 as e,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"修补 Linux 系统 glibc 严重漏洞 | LCTT x X-CMD","titleTemplate":false,"description":"修补 Linux 系统 glibc 严重漏洞 | LCTT (201606) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修补 Linux 系统 glibc 严重漏洞 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修补 Linux 系统 glibc 严重漏洞 | LCTT (201606) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201606/20160218 Linux Systems Patched for Critical glibc Flaw","title":"修补 Linux 系统 glibc 严重漏洞","tag":"201606","desc":""},"relativePath":"201606/20160218 Linux Systems Patched for Critical glibc Flaw.md","filePath":"[post].md"}'),b={name:"201606/20160218 Linux Systems Patched for Critical glibc Flaw.md"};function a(d,t,x,m,f,L){const n=s("Link");return o(),p("div",null,[t[16]||(t[16]=g('<h1 id="修补-linux-系统-glibc-严重漏洞" tabindex="-1">修补 Linux 系统 glibc 严重漏洞 <a class="header-anchor" href="#修补-linux-系统-glibc-严重漏洞" aria-label="Permalink to “修补 Linux 系统 glibc 严重漏洞”">​</a></h1><p><strong>谷歌披露的一个严重漏洞影响到了主流的 Linux 发行版。glibc 的漏洞可能导致远程代码执行。</strong></p><p>编者按：这个消息并不是一个新闻，基于技术的原因，我们还是分享给大家。</p><p>Linux 用户都在竞相给一个可以使系统暴露在远程代码执行风险中的核心 glibc 开放源码库的严重漏洞打补丁。这个 glibc 的漏洞编号被确定为 CVE-2015-7547，题为“getaddrinfo 基于堆栈的缓冲区溢出”。</p><p>glibc，或 GNU C 库，是一个开放源码的 C 和 C++ 编程语言库的实现，是每一个主流 Linux 发行版的一部分。谷歌工程师们在他们试图连接到某个主机系统时发生了一个段错误导致连接崩溃，偶然发现了 CVE-2015-7547 问题。进一步的研究表明， glibc 有缺陷而且该崩溃可能实现任意远程代码执行的条件。</p><p>谷歌在一篇博客文章中写道, “当 getaddrinfo() 库函数被使用时，glibc 的 DNS 客户端解析器易受基于堆栈缓冲区溢出的攻击，使用该功能的软件可能通过攻击者控制的域名、攻击者控制的 DNS [域名系统] 服务器，或通过中间人攻击方式（MITM）进行破坏。”</p><p>其实利用 CVE-2015-7547 问题并不简单，但它是可能的。为了证明这个问题能被利用，谷歌发布了论证一个终端用户或系统是否易受攻击的概念验证（POC）代码到 GitHub 上。</p><p>GitHub 上的 POC 网页说“服务器代码会触发漏洞，因此会使客户端代码崩溃”。</p><p>Duo Security 公司的高级安全研究员 Mark Loveless 解释说 CVE-2015-7547 的主要风险在于依赖于 DNS 响应的基于 Linux 客户端的应用程序。</p><p>Loveless 告诉 eWEEK “需要一些特定的条件，所以不是每个应用程序都会受到影响，但似乎一些命令行工具，包括流行的 SSH[安全 Shell] 客户端都可能触发该漏洞，我们认为这是严重的，主要是因为对 Linux 系统存在的风险，但也因为潜在的其他问题。”</p><p>其他问题可能包括一种通过电子邮件触发调用易受攻击的 glibc 库 getaddrinfo() 攻击的风险。另外值得注意的是，该漏洞被发现之前已存在于代码之中多年。</p>',11)),l("p",null,[t[1]||(t[1]=i("谷歌的工程师不是第一或唯一发现这个 glibc 安全风险的团体。这个问题于 2015 年 7 月 13 日首先被报告给了 glibc 的 bug",-1)),e(n,{href:"https://sourceware.org/bugzilla/show_bug.cgi?id=1866"},{default:r(()=>[...t[0]||(t[0]=[i("跟踪系统",-1)])]),_:1}),t[2]||(t[2]=i("。该缺陷的根源可以更进一步追溯到在 2008 五月发布的 glibc 2.9 的代码提交时首次引入缺陷。",-1))]),t[17]||(t[17]=l("p",null,"Linux 厂商红帽也独立找到了 glibc 中的这个 bug，而且是在 2016 年 1 月 6 日，谷歌和红帽开发人员证实，他们作为最初与上游 glibc 的维护者私下讨论的部分人员，已经独立在为同一个漏洞工作。",-1)),t[18]||(t[18]=l("p",null,"红帽产品安全首席软件工程师 Florian Weimer 告诉 eWEEK “一旦确认了两个团队都在为同一个漏洞工作，我们会合作进行可能的修复，缓解措施和回归测试，我们还会共同努力，使测试覆盖尽可能广，捕捉代码中的任何相关问题，以帮助避免今后更多问题。”",-1)),t[19]||(t[19]=l("p",null,"由于缺陷不明显或不易立即显现，我们花了几年时间才发现 glibc 代码有一个安全问题。",-1)),t[20]||(t[20]=l("p",null,"Weimer 说“要诊断一个网络组件的漏洞，如 DNS 解析器，当遇到问题时通常要看抓到的数据包的踪迹，在这种情况下这样的抓包不适用，所以需要一些实验来重现触发这个 bug 的确切场景。”",-1)),t[21]||(t[21]=l("p",null,"Weimer 补充说，一旦可以抓取数据包，就会投入大量精力到验证修复程序中，最终完成回归测试套件一系列的改进，有助于上游 glibc 项目。",-1)),t[22]||(t[22]=l("p",null,"在许多情况下，安全增强式 Linux (SELinux) 的强制访问安全控制可以减少潜在漏洞风险，但是这个 glibc 的新问题例外。",-1)),t[23]||(t[23]=l("p",null,"Weimer 说“由于攻击者提供的任意代码的执行，会对很多重要系统功能带来风险。一个合适的 SELinux 策略可以遏制一些攻击者可能会做的损害，并限制他们访问系统，但是 DNS 被许多应用程序和系统组件使用，所以 SELinux 策略只提供了针对此问题有限的遏制。”",-1)),t[24]||(t[24]=l("p",null,"在揭露漏洞的今天，现在有一个可用的补丁来减少 CVE-2015-7547 的潜在风险。",-1)),t[25]||(t[25]=l("hr",null,null,-1)),l("p",null,[t[4]||(t[4]=i("via: ",-1)),e(n,{href:"http://www.eweek.com/security/linux-systems-patched-for-critical-glibc-flaw.html"},{default:r(()=>[...t[3]||(t[3]=[i("http://www.eweek.com/security/linux-systems-patched-for-critical-glibc-flaw.html",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=i("作者：",-1)),e(n,{href:"https://twitter.com/TechJournalist"},{default:r(()=>[...t[5]||(t[5]=[i("Michael Kerner",-1)])]),_:1}),t[9]||(t[9]=i(" 译者：",-1)),e(n,{href:"https://github.com/robot527"},{default:r(()=>[...t[6]||(t[6]=[i("robot527",-1)])]),_:1}),t[10]||(t[10]=i(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[7]||(t[7]=[i("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[11]||(t[11]=[i("LCTT",-1)])]),_:1}),t[14]||(t[14]=i(" 原创翻译，",-1)),e(n,{href:"https://linux.cn/"},{default:r(()=>[...t[12]||(t[12]=[i("Linux 中国",-1)])]),_:1}),t[15]||(t[15]=i(" 荣誉推出",-1))])])}const S=u(b,[["render",a]]);export{w as __pageData,S as default};
